// dashboard.mjs — weekly wait-time summary for the front desk.
// Spec: README.md. Timestamps are local clinic wall-clock "YYYY-MM-DD HH:MM" with no zone.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { resolve } from 'node:path';

export function parse(text) {
  const lines = text.split(/\r?\n/).map((l) => l.trim()).filter((l) => l !== '');
  if (!lines.length) return [];
  const cols = lines[0].split(',').map((c) => c.trim());
  return lines.slice(1).map((l) => Object.fromEntries(l.split(',').map((v, i) => [cols[i], v.trim()])));
}

// Wall-clock timestamps are read as if they were UTC, so the arithmetic never depends on the
// machine's time zone or its daylight-saving rules (the spec says: no time zones involved).
const wall = (ts) => {
  const t = /^\d{4}-\d\d-\d\d \d\d:\d\d$/.test(ts) ? Date.parse(ts.replace(' ', 'T') + 'Z') : NaN;
  if (Number.isNaN(t)) throw new Error(`bad timestamp: ${JSON.stringify(ts)}`);
  return t;
};

export const minutes = (a, b) => (wall(b) - wall(a)) / 60000;

export function weekOf(ts) {
  const d = new Date(wall(ts));
  d.setUTCHours(0, 0);
  d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7)); // back to Monday
  return d.toISOString().slice(0, 10);
}

export function median(xs) {
  const s = [...xs].sort((a, b) => a - b);
  if (!s.length) return null;
  const mid = s.length >> 1;
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

export function summarize(rows) {
  const weeks = new Map();
  for (const r of rows) {
    const w = weekOf(r.signed_in);
    if (!weeks.has(w)) weeks.set(w, { visits: 0, waits: [] });
    const wk = weeks.get(w);
    wk.visits++;
    if (r.seen_at) wk.waits.push(minutes(r.signed_in, r.seen_at));
  }
  return [...weeks.keys()].sort().map((week) => {
    const { visits, waits } = weeks.get(week);
    return { week, visits, seen: waits.length, walkouts: visits - waits.length, median_wait_min: median(waits) };
  });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (!process.argv[2]) {
    console.error('usage: node dashboard.mjs visits.csv');
    process.exit(2);
  }
  for (const w of summarize(parse(readFileSync(process.argv[2], 'utf8')))) console.log(JSON.stringify(w));
}

