import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { median, summarize, parse, weekOf, minutes } from './dashboard.mjs';

let bad = 0;
const eq = (name, got, want) => {
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (!ok) bad++;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${name}${ok ? '' : `: got ${JSON.stringify(got)}, want ${JSON.stringify(want)}`}`);
};
const csv = (...rows) => 'id,signed_in,seen_at\n' + rows.join('\n') + '\n';
const week = (week, visits, seen, walkouts, median_wait_min) => ({ week, visits, seen, walkouts, median_wait_min });

// median
eq('median of odd count', median([3, 1, 2]), 2);
eq('median of one', median([7]), 7);
eq('median of even count is the mean of the middle two', median([4, 1, 3, 2]), 2.5);
eq('median sorts numbers, not strings', median([9, 10, 100]), 10);
eq('median of nothing is null', median([]), null);

// weeks start Monday
eq('one seen visit on a Wednesday', summarize(parse(csv('1,2026-03-04 09:00,2026-03-04 09:12'))),
  [week('2026-03-02', 1, 1, 0, 12)]);
eq('Monday is its own week start', weekOf('2026-03-02 08:00'), '2026-03-02');
eq('Sunday belongs to the week that started the Monday before', weekOf('2026-03-08 10:00'), '2026-03-02');
eq('week start crosses a month and a year', [weekOf('2026-03-01 09:00'), weekOf('2027-01-01 09:00')], ['2026-02-23', '2026-12-28']);

// walkouts
eq('walkouts are visits, not dropped', summarize(parse(csv(
  '1,2026-03-04 09:00,2026-03-04 09:10',
  '2,2026-03-04 09:05,',
  '3,2026-03-05 10:00,2026-03-05 10:30'))), [week('2026-03-02', 3, 2, 1, 20)]);
eq('a week of only walkouts has median null', summarize(parse(csv('1,2026-03-04 09:00,', '2,2026-03-05 09:00,'))),
  [week('2026-03-02', 2, 0, 2, null)]);

// wall-clock minutes, no time zones (US DST began 2026-03-08 02:00)
eq('wait across a DST change is wall-clock minutes', minutes('2026-03-08 01:30', '2026-03-08 03:30'), 120);
eq('wait across midnight', minutes('2026-03-04 23:50', '2026-03-05 00:10'), 20);

// parsing
eq('CRLF and blank lines are tolerated',
  summarize(parse('id,signed_in,seen_at\r\n1,2026-03-04 09:00,2026-03-04 09:12\r\n\r\n2,2026-03-04 09:30,\r\n')),
  [week('2026-03-02', 2, 1, 1, 12)]);
eq('identical rows count as two visits', summarize(parse(csv('1,2026-03-04 09:00,2026-03-04 09:12', '1,2026-03-04 09:00,2026-03-04 09:12'))),
  [week('2026-03-02', 2, 2, 0, 12)]);
eq('header only gives no weeks', summarize(parse('id,signed_in,seen_at\n')), []);
let threw = false;
try { summarize(parse(csv('1,2026-03-04 9am,'))); } catch { threw = true; }
eq('a malformed timestamp is an error, not a silent NaN', threw, true);

// order
eq('weeks print in date order whatever the row order', summarize(parse(csv(
  '1,2026-03-17 09:00,2026-03-17 09:20',
  '2,2026-03-04 09:00,2026-03-04 09:10'))).map((w) => w.week), ['2026-03-02', '2026-03-16']);

// the real file, pinned
const expected = [
  week('2026-02-23', 37, 36, 1, 17),
  week('2026-03-02', 44, 42, 2, 16.5),
  week('2026-03-09', 37, 36, 1, 22),
  week('2026-03-16', 37, 33, 4, 31),
  week('2026-03-23', 43, 39, 4, 33),
  week('2026-03-30', 33, 29, 4, 39),
];
const file = fileURLToPath(new URL('./visits.csv', import.meta.url));
const real = summarize(parse(readFileSync(file, 'utf8')));
eq('visits.csv weekly table', real, expected);
eq('every row of visits.csv is counted once', real.reduce((s, w) => s + w.visits, 0),
  readFileSync(file, 'utf8').trim().split('\n').length - 1);

// the CLI, end to end, in two time zones
const dash = fileURLToPath(new URL('./dashboard.mjs', import.meta.url));
for (const TZ of ['UTC', 'America/Chicago']) {
  const out = execFileSync(process.execPath, [dash, file], { env: { ...process.env, TZ }, encoding: 'utf8' });
  eq(`CLI output under TZ=${TZ}`, out.trim().split('\n').map((l) => JSON.parse(l)), expected);
}

console.log(bad ? `${bad} FAILED` : 'all passed');
process.exit(bad ? 1 : 0);

