// assign.mjs — who works when, under POLICY.md.
//
// Every rule in POLICY.md is a hard constraint. The program either returns a rota that obeys all
// five, or throws with the reason. It never quietly bends one: which rule gives way when they clash
// is the clinic's decision, not this program's.
//
// Method: depth-first search, day by day. Each day it tries first the pairs furthest behind their
// fair share (with a stronger pull on weekends). Ties are broken by a permutation of the names
// seeded from the start date, NOT by file or alphabetical order. That way the rounding surplus
// doesn't land on the same people in every rota. Pruning uses only necessary conditions, so a
// search that finishes without a rota is a proof that none exists. A search that runs out of
// budget says "gave up", not "impossible".
import { days as calendarDays, isWeekend } from './calendar.mjs';

export const MAX_RUN = 5;      // rule 3
export const TOL_TOTAL = 2;    // rule 4
export const TOL_WEEKEND = 1.5; // rule 5
const EPS = 1e-9;

// Rule 4/5 shares, exactly as the policy words them.
export function fairShares(people, start, n) {
  const ds = calendarDays(start, n);
  const nWeekend = ds.filter(isWeekend).length;
  const weights = people.map((p) => (p.fte * ds.filter((d) => !p.leave.has(d)).length) / n);
  const W = weights.reduce((a, b) => a + b, 0);
  if (!(W > 0)) throw new Error('nobody has any weight (all fte 0 or all on leave), so fair shares are undefined');
  return people.map((p, i) => ({
    name: p.name,
    weight: weights[i],
    total: (2 * n * weights[i]) / W,
    weekend: (2 * nWeekend * weights[i]) / W,
  }));
}

// Small seeded PRNG + string hash, so a period's rota is reproducible.
function hash(s) {
  let h = 2166136261;
  for (const c of s) h = Math.imul(h ^ c.codePointAt(0), 16777619);
  return h >>> 0;
}
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function makeRota(people, start, n, opts = {}) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start || '') || Number.isNaN(Date.parse(`${start}T00:00:00Z`)))
    throw new Error(`bad start date: ${start}`);
  if (!Number.isInteger(n) || n < 1) throw new Error(`bad number of days: ${n}`);
  const { firstBudget = 2000, totalBudget = 2_000_000, carry = null } = opts;

  // Canonical order (by name) so the file's order can't change the result.
  const team = [...people].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  const P = team.length;
  const ds = calendarDays(start, n);
  const wk = ds.map(isWeekend);
  const shares = fairShares(team, start, n);
  const nurse = team.map((p) => p.role === 'nurse');
  const avail = team.map((p) => ds.map((d) => !p.leave.has(d)));

  // Bounds from rules 4 and 5.
  const lo = shares.map((s) => Math.max(0, Math.ceil(s.total - TOL_TOTAL - EPS)));
  const hi = shares.map((s) => Math.floor(s.total + TOL_TOTAL + EPS));
  const wlo = shares.map((s) => Math.max(0, Math.ceil(s.weekend - TOL_WEEKEND - EPS)));
  const whi = shares.map((s) => Math.floor(s.weekend + TOL_WEEKEND + EPS));

  // cap[i][d][r] = most days person i can still work from day d on, having worked r days in a row
  // just before d. Working whenever allowed is optimal, so a greedy pass gives the exact maximum.
  const cap = [], wcap = [];
  for (let i = 0; i < P; i++) {
    cap.push([]); wcap.push([]);
    for (let d = 0; d <= n; d++) { cap[i].push(new Int32Array(MAX_RUN + 1)); wcap[i].push(new Int32Array(MAX_RUN + 1)); }
    for (let d = n - 1; d >= 0; d--) for (let r = 0; r <= MAX_RUN; r++) {
      if (avail[i][d] && r < MAX_RUN) {
        // Working today is never worse for the plain count; for the weekend count try both.
        const work = 1 + cap[i][d + 1][r + 1], rest = cap[i][d + 1][0];
        cap[i][d][r] = Math.max(work, rest);
        wcap[i][d][r] = Math.max((wk[d] ? 1 : 0) + wcap[i][d + 1][r + 1], wcap[i][d + 1][0]);
      } else {
        cap[i][d][r] = cap[i][d + 1][0];
        wcap[i][d][r] = wcap[i][d + 1][0];
      }
    }
  }
  // availSoFar[i][d] = days in [0, d) person i is not on leave (wAvailSoFar: weekend days only).
  const availSoFar = [], wAvailSoFar = [];
  for (let i = 0; i < P; i++) {
    const a = new Int32Array(n + 1), w = new Int32Array(n + 1);
    for (let d = 0; d < n; d++) { a[d + 1] = a[d] + (avail[i][d] ? 1 : 0); w[d + 1] = w[d] + (avail[i][d] && wk[d] ? 1 : 0); }
    availSoFar.push(a); wAvailSoFar.push(w);
  }
  const weekendsLeft = new Int32Array(n + 1);
  for (let d = n - 1; d >= 0; d--) weekendsLeft[d] = weekendsLeft[d + 1] + (wk[d] ? 1 : 0);

  explainUpFront();

  // ----- search -----
  const cnt = new Int32Array(P), wcnt = new Int32Array(P), run = new Int32Array(P);
  const choice = new Array(n);
  let nodes = 0, budget = 0, order = [], jitter = null, aim = [], waim = [];
  // carry = { name: { total, weekend } }: how far each person is ahead (+) or behind (−) of their
  // share over earlier rotas. One rota repays at most the policy's own tolerance; the rest waits.
  const clamp = (x, t) => Math.max(-t, Math.min(t, Number(x) || 0));
  const clampedCarry = team.map((p) => ({
    total: clamp(carry?.[p.name]?.total, TOL_TOTAL),
    weekend: clamp(carry?.[p.name]?.weekend, TOL_WEEKEND),
  }));

  function feasibleFrom(d) {
    const left = n - d, wleft = weekendsLeft[d];
    let needSum = 0, roomSum = 0, wneedSum = 0, wroomSum = 0, nurseRoom = 0, aideNeed = 0;
    for (let i = 0; i < P; i++) {
      const c = Math.min(cap[i][d][run[i]], hi[i] - cnt[i]);
      const need = lo[i] - cnt[i];
      if (hi[i] < cnt[i] || cap[i][d][run[i]] < need) return false;
      const wc = Math.min(wcap[i][d][run[i]], whi[i] - wcnt[i]);
      const wneed = wlo[i] - wcnt[i];
      if (whi[i] < wcnt[i] || wcap[i][d][run[i]] < wneed) return false;
      needSum += Math.max(0, need); roomSum += c;
      wneedSum += Math.max(0, wneed); wroomSum += wc;
      if (nurse[i]) nurseRoom += c; else aideNeed += Math.max(0, need);
    }
    // Two a day; at least one nurse a day, so aides get at most one slot a day.
    return needSum <= 2 * left && roomSum >= 2 * left && wneedSum <= 2 * wleft && wroomSum >= 2 * wleft
      && nurseRoom >= left && aideNeed <= left;
  }

  function candidates(d) {
    // "Behind" is measured against each person's OWN available days, not the calendar. Someone with
    // leave late in the period must get ahead before it. Pacing them by the calendar put the only
    // aide of a 4-person team two weekend shifts short on the last weekend, and the search gave up
    // on a team that has a rota. With no leave this is the same as (d + 1) / n.
    const score = [];
