// people.mjs — load and validate the team file.
import { readFileSync } from 'node:fs';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

export function validatePeople(people) {
  if (!Array.isArray(people)) throw new Error('team file must be a JSON list of people');
  const seen = new Set();
  for (const p of people) {
    if (!p || typeof p.name !== 'string' || !p.name || !['nurse', 'aide'].includes(p.role))
      throw new Error(`bad person: ${JSON.stringify(p)}`);
    if (seen.has(p.name)) throw new Error(`duplicate name: ${p.name}`);
    seen.add(p.name);
    p.fte = Number(p.fte ?? 1);
    // fte above 1 is refused on purpose: it also catches "80" meaning 80%.
    if (!(p.fte >= 0 && p.fte <= 1)) throw new Error(`${p.name}: fte must be between 0 and 1, got ${JSON.stringify(p.fte)}`);
    const leave = [...(p.leave || [])];
    for (const d of leave)
      if (typeof d !== 'string' || !DATE.test(d) || Number.isNaN(Date.parse(`${d}T00:00:00Z`)))
        throw new Error(`${p.name}: bad leave date ${JSON.stringify(d)} (want YYYY-MM-DD)`);
    p.leave = new Set(leave);
  }
  return people;
}

export function loadPeople(path) {
  return validatePeople(JSON.parse(readFileSync(path, 'utf8')));
}

