// Cumulative surplus over K consecutive 4-week rotas, with or without the ledger ("carry" arg).
// usage: node scratch-mor-drift.mjs K START [carry]
const { makeRota, ledger } = await import(process.argv[5] || './lib/assign.mjs'); // 5th arg: module path
import { loadPeople } from './lib/people.mjs';
import { days } from './lib/calendar.mjs';
const team = loadPeople('people.json'), K = +(process.argv[2] || 13), start0 = process.argv[3] || '2026-11-02', useCarry = process.argv[4] === 'carry';
const rotas = [];
let start = start0, worst = [0, 0];
for (let k = 0; k < K; k++) {
  const carry = useCarry ? ledger(team, rotas) : null;
  rotas.push(makeRota(team, start, 28, { carry }));
  for (const v of Object.values(ledger(team, rotas))) { worst[0] = Math.max(worst[0], Math.abs(v.total)); worst[1] = Math.max(worst[1], Math.abs(v.weekend)); }
  start = days(start, 29)[28];
}
const L = ledger(team, rotas);
console.log(useCarry ? 'carry' : 'plain', start0, K, 'end:', Object.entries(L).map(([k, v]) => `${k}:${v.total.toFixed(1)}/${v.weekend.toFixed(1)}`).join(' '), '| worst ever:', worst.map((x) => x.toFixed(1)).join('/'));

