// Mutation check: each mutant of assign.mjs should make at least one test fail.
import { cpSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
const here = new URL('.', import.meta.url).pathname;
const muts = [
  ['MAX_RUN = 5', 'MAX_RUN = 6'],
  ['TOL_WEEKEND = 1.5', 'TOL_WEEKEND = 3'],
  ['TOL_TOTAL = 2', 'TOL_TOTAL = 3'],
  ['&& nurseRoom >= left && aideNeed <= left', '&& true'],
  ['order = shuffledRanks(P, r)', 'order = [...Array(P).keys()]'],
  ['if (nurseMax < n)', 'if (nurseMax < n - 3)'],
  ['if (aideMin > n)', 'if (aideMin > n + 3)'],
  ['if (d === n) return feasibleFrom(n);', 'if (d === n) return true;'],
  ['const useCarry = carry && spent < totalBudget / 4;', 'const useCarry = false;'],
];
for (const [a, b] of muts) {
  const dir = `/tmp/mut-${process.pid}`;
  rmSync(dir, { recursive: true, force: true });
  cpSync(here, dir, { recursive: true });
  const f = `${dir}/lib/assign.mjs`, src = readFileSync(f, 'utf8');
  if (!src.includes(a)) { console.log(`MISSING ${a}`); continue; }
  writeFileSync(f, src.replace(a, b));
  const r = spawnSync('node', ['test.mjs'], { cwd: dir, encoding: 'utf8', timeout: 120000 });
  const fails = (r.stdout || '').split('\n').filter((l) => l.startsWith('FAIL'));
  // A crash (uncaught throw, timeout) is also a catch: the suite did not pass. (Modulo)
  const why = fails.length ? fails.slice(0, 2).join(' | ') : `exit ${r.status} ${(r.stderr || '').split('\n').find((l) => l.startsWith('Error')) || ''}`;
  console.log(`${fails.length || r.status !== 0 ? 'caught ' : 'MISSED '} ${b}  ${why.slice(0, 160)}`);
  rmSync(dir, { recursive: true, force: true });
}

