// 1000 random teams (3–9 people, 1–365 days, random leave): count made / refused-by-reason / gave up.
const { makeRota } = await import(process.argv[3] || './lib/assign.mjs'); // node scratch-mor-stress.mjs SEED [module]
import { days } from './lib/calendar.mjs';
let seed = +(process.argv[2] || 1);
const rnd = () => ((seed = (seed * 1103515245 + 12345) >>> 0) / 4294967296);
const why = {}; let made = 0, worst = 0;
for (let k = 0; k < 1000; k++) {
  const size = 3 + Math.floor(rnd() * 7), n = 1 + Math.floor(rnd() * (rnd() < 0.2 ? 365 : 91));
  const start = new Date(Date.UTC(2026, 0, 1) + Math.floor(rnd() * 365) * 864e5).toISOString().slice(0, 10);
  const ds = days(start, n);
  const t = Array.from({ length: size }, (_, i) => ({ name: `P${i}`, role: i === 0 || rnd() < 0.5 ? 'nurse' : 'aide',
    fte: [1, 1, 1, 0.8, 0.6, 0.5][Math.floor(rnd() * 6)], leave: new Set(rnd() < 0.4 ? ds.slice(Math.floor(rnd() * n)).slice(0, 1 + Math.floor(rnd() * 10)) : []) }));
  const t0 = Date.now();
  try { makeRota(t, start, n); made++; } catch (e) { const key = e.message.replace(/[\d.-]+|P\d+/g, '#').slice(0, 60); why[key] = (why[key] || 0) + 1; }
  worst = Math.max(worst, Date.now() - t0);
}
console.log({ made, worstMs: worst, why });

