import { execFileSync, spawnSync } from 'node:child_process';
import { writeFileSync, unlinkSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { makeRota, fairShares, ledger } from './lib/assign.mjs';
import { days, isWeekend } from './lib/calendar.mjs';
import { loadPeople, validatePeople } from './lib/people.mjs';

let bad = 0;
const ok = (name, cond, extra = '') => { if (!cond) bad++; console.log(`${cond ? 'ok  ' : 'FAIL'} ${name}${cond ? '' : ` ${extra}`}`); };
const throws = (fn, re) => { try { fn(); return false; } catch (e) { return re.test(e.message); } };

// ---------- Independent policy checker (does not use the solver's share code) ----------
function policyViolations(team, start, n, rota) {
  const v = [];
  const ds = [];
  for (let i = 0; i < n; i++) ds.push(new Date(Date.UTC(...start.split('-').map((x, k) => +x - (k === 1 ? 1 : 0))) + i * 864e5).toISOString().slice(0, 10));
  const weekend = (d) => { const g = new Date(d + 'T12:00:00Z').getUTCDay(); return g === 0 || g === 6; };
  const byName = new Map(team.map((p) => [p.name, p]));
  if (Object.keys(rota).length !== n || ds.some((d) => !rota[d])) v.push('rota does not cover exactly the period');
  const tot = new Map(team.map((p) => [p.name, 0])), wkd = new Map(team.map((p) => [p.name, 0]));
  const streak = new Map(team.map((p) => [p.name, 0]));
  for (const d of ds) {
    const on = rota[d] || [];
    if (on.length !== 2 || new Set(on).size !== 2 || on.some((x) => !byName.has(x))) { v.push(`rule 1: ${d} is not two distinct team members`); continue; }
    if (!on.some((x) => byName.get(x).role === 'nurse')) v.push(`rule 1: no nurse on ${d}`);
    for (const x of on) {
      const lv = byName.get(x).leave;
      if (lv instanceof Set ? lv.has(d) : lv.includes(d)) v.push(`rule 2: ${x} on leave ${d}`);
      tot.set(x, tot.get(x) + 1);
      if (weekend(d)) wkd.set(x, wkd.get(x) + 1);
    }
    for (const p of team) {
      streak.set(p.name, on.includes(p.name) ? streak.get(p.name) + 1 : 0);
      if (streak.get(p.name) === 6) v.push(`rule 3: ${p.name} 6 days in a row ending ${d}`);
    }
  }
  const nW = ds.filter(weekend).length;
  const w = team.map((p) => p.fte * ds.filter((d) => !(p.leave instanceof Set ? p.leave.has(d) : p.leave.includes(d))).length / n);
  const W = w.reduce((a, b) => a + b, 0);
  team.forEach((p, i) => {
    const share = 2 * n * w[i] / W, wshare = 2 * nW * w[i] / W;
    if (Math.abs(tot.get(p.name) - share) > 2 + 1e-9) v.push(`rule 4: ${p.name} ${tot.get(p.name)} vs share ${share.toFixed(2)}`);
    if (Math.abs(wkd.get(p.name) - wshare) > 1.5 + 1e-9) v.push(`rule 5: ${p.name} ${wkd.get(p.name)} vs weekend share ${wshare.toFixed(2)}`);
  });
  return v;
}

// ---------- Original tests ----------
const team = [
  { name: 'Ana', role: 'nurse', fte: 1, leave: new Set() },
  { name: 'Bea', role: 'aide', fte: 1, leave: new Set(['2026-11-03']) },
  { name: 'Cy', role: 'nurse', fte: 1, leave: new Set() },
];
ok('seven days', days('2026-11-02', 7).length === 7);
ok('Saturday is a weekend', isWeekend('2026-11-07') && !isWeekend('2026-11-06'));
const r = makeRota(team, '2026-11-02', 7);
ok('two people a day', Object.values(r).every((d) => d.length === 2 && new Set(d).size === 2));
ok('a nurse every day', Object.values(r).every((d) => d.some((n) => team.find((p) => p.name === n).role === 'nurse')));
ok('leave is honoured', !r['2026-11-03'].includes('Bea'));
ok('small team obeys the whole policy', policyViolations(team, '2026-11-02', 7, r).length === 0, policyViolations(team, '2026-11-02', 7, r));

// ---------- The checker catches each kind of breach ----------
{
  const t = [
    { name: 'A', role: 'nurse', fte: 1, leave: new Set(['2026-11-04']) },
    { name: 'B', role: 'aide', fte: 1, leave: new Set() },
    { name: 'C', role: 'aide', fte: 1, leave: new Set() },
  ];
  const ds = days('2026-11-02', 7);
  const has = (rota, re) => policyViolations(t, '2026-11-02', 7, rota).some((m) => re.test(m));
  const all = (pair) => Object.fromEntries(ds.map((d) => [d, pair]));
  ok('checker: no nurse', has(all(['B', 'C']), /rule 1: no nurse/));
  ok('checker: one person', has({ ...all(['A', 'B']), [ds[0]]: ['A', 'A'] }, /rule 1: .* not two/));
  ok('checker: leave', has(all(['A', 'B']), /rule 2: A/));
  ok('checker: rest', has(all(['A', 'B']), /rule 3: B 6 days/));
  ok('checker: fair share', has(all(['A', 'B']), /rule 4: C 0/));
  const ds14 = days('2026-11-02', 14);
  ok('checker: weekend share', policyViolations(t, '2026-11-02', 14, Object.fromEntries(ds14.map((d) => [d, isWeekend(d) ? ['A', 'B'] : ['A', 'C']]))).some((m) => /rule 5: C 0/.test(m)));
  ok('checker: missing day', has({ [ds[0]]: ['A', 'B'] }, /cover exactly/));
}

// ---------- The real team ----------
const clinic = loadPeople(new URL('./people.json', import.meta.url).pathname);
for (const [start, n] of [['2026-11-02', 28], ['2026-11-07', 28], ['2026-11-02', 1], ['2026-11-02', 91], ['2026-11-02', 365], ['2027-01-04', 28]]) {
  const rota = makeRota(clinic, start, n);
  const v = policyViolations(clinic, start, n, rota);
  ok(`clinic ${start} + ${n} days obeys the policy`, v.length === 0, v.slice(0, 3));
}

// The staff complaint, as a test: not alphabetical, and Yusuf gets weekends.
{
  const rota = makeRota(clinic, '2026-11-02', 28);
  const count = (name, pred = () => true) => Object.entries(rota).filter(([d, on]) => pred(d) && on.includes(name)).length;
  ok('Ana does not work every day', count('Ana') < 28);
  ok('Yusuf gets weekend shifts', count('Yusuf', isWeekend) >= 1);
  const sh = fairShares(clinic, '2026-11-02', 28);
  ok('November: everyone within 1 of their share', sh.every((s) => Math.abs(count(s.name) - s.total) <= 1), sh.map((s) => `${s.name}:${count(s.name)}/${s.total.toFixed(2)}`));
}

// The file's order (alphabetical or not) must not change the rota.
{
  const a = makeRota(clinic, '2026-11-02', 28), b = makeRota([...clinic].reverse(), '2026-11-02', 28);
  ok('team file order does not change the rota', JSON.stringify(a) === JSON.stringify(b));
}

// ---------- Edge cases ----------
{
  const t = clinic.map((p) => ({ ...p, fte: p.name === 'Ana' ? 0 : p.fte }));
  const rota = makeRota(t, '2026-11-02', 28);
  ok('fte 0: still lawful', policyViolations(t, '2026-11-02', 28, rota).length === 0);
  ok('fte 0 has zero share', fairShares(t, '2026-11-02', 28).find((s) => s.name === 'Ana').total === 0);
}
ok('refuses: no nurse on a day', throws(() => makeRota([
  { name: 'N', role: 'nurse', fte: 1, leave: new Set(['2026-11-03']) },
  { name: 'A', role: 'aide', fte: 1, leave: new Set() },
  { name: 'B', role: 'aide', fte: 1, leave: new Set() }], '2026-11-02', 3), /no nurse available on 2026-11-03/));
ok('refuses: fewer than two people', throws(() => makeRota([
  { name: 'N', role: 'nurse', fte: 1, leave: new Set() },
  { name: 'M', role: 'nurse', fte: 1, leave: new Set(['2026-11-02']) }], '2026-11-02', 2), /fewer than two/));
ok('refuses: two people cannot cover 6 days (rest)', throws(() => makeRota([
  { name: 'N', role: 'nurse', fte: 1, leave: new Set() },
  { name: 'M', role: 'nurse', fte: 1, leave: new Set() }], '2026-11-02', 6), /./));
ok('refuses: one part-time nurse cannot cover every day', throws(() => makeRota([
  { name: 'N', role: 'nurse', fte: 0.5, leave: new Set() },
  { name: 'A', role: 'aide', fte: 1, leave: new Set() },
  { name: 'B', role: 'aide', fte: 1, leave: new Set() }], '2026-11-02', 28), /nurse/));
ok('refuses: bad start date', throws(() => makeRota(clinic, '2026-13-40', 7), /bad start/));
ok('refuses: zero days', throws(() => makeRota(clinic, '2026-11-02', 0), /bad number/));
ok('validate: duplicate names', throws(() => validatePeople([{ name: 'A', role: 'nurse' }, { name: 'A', role: 'aide' }]), /duplicate/));
ok('validate: fte 80', throws(() => validatePeople([{ name: 'A', role: 'nurse', fte: 80 }]), /fte/));
ok('validate: bad leave date', throws(() => validatePeople([{ name: 'A', role: 'nurse', leave: ['11/03/2026'] }]), /leave date/));
ok('validate: unknown role', throws(() => validatePeople([{ name: 'A', role: 'doctor' }]), /bad person/));

// ---------- Random teams and periods ----------
// Every rota must obey the policy. Every refusal must be a proof (a message naming a rule clash
// or an exhaustive search), never "gave up".
{
  let seed = 12345;
  const rnd = () => ((seed = (seed * 1103515245 + 12345) >>> 0) / 4294967296);
  let made = 0, refused = 0, gaveUp = 0, broken = [];
  for (let k = 0; k < 200; k++) {
    const size = 3 + Math.floor(rnd() * 7);
    const start = new Date(Date.UTC(2026, 0, 1) + Math.floor(rnd() * 365) * 864e5).toISOString().slice(0, 10);
    const n = 1 + Math.floor(rnd() * 91);
    const ds = days(start, n);
    const t = Array.from({ length: size }, (_, i) => ({
      name: `P${i}`, role: i === 0 || rnd() < 0.5 ? 'nurse' : 'aide',
      fte: [1, 1, 1, 0.8, 0.6, 0.5][Math.floor(rnd() * 6)],
      leave: new Set(rnd() < 0.4 ? ds.slice(Math.floor(rnd() * n)).slice(0, 1 + Math.floor(rnd() * 7)) : []),
    }));
    try {
      const rota = makeRota(t, start, n);
